map:
# 배치 v7: 벽 안쪽 1.98 x 0.98 m 경기장. 진열대 3개와 충전 칸막이 2개.
# 급행 줄은 y 0.882이고 지도 벽은 0.98이다. 진열대 서쪽 HALL 띠는 x 0.598까지만 늘린다.
#
#   y
#  0.98 +---------------+---------------------------------+----------+
#       |   O  OUT_DOCK | O_X        EXPRESS  <-----------|      J_E |  급행 줄 y 0.882, O_X 급행 서쪽 끝 대기
# 0.794 |               |    +============================+          |  진열대 A y 0.754~0.794, x 0.654~1.574
#  0.765+------+        |    |          진열대 A          |     W_X  |  (1.803, 0.845) 원호 위, 급행 들머리
# 0.754 |                    +============================+          |
#       | O_OUT    O_IN            가운데 통로                   M_E    |  y 0.62 출고의 두 점, M_E y 0.55
#       |                                                         [W]|  WORK (1.86, 0.495), 북쪽 보기
# 0.404 |                +===========+   틈   +===========+          |  진열대 y 0.364~0.404, x 0.704~1.014, 1.264~1.574
#       | E-1   E-2   E-3          남쪽 통로                       Q1 |  y 0.24~0.26, 칸 입구와 줄 앞자리
#       | P-1 | P-2 | P-3                                  Q2  -^    |  y 0.10 충전 칸, y 0.15 줄 입구
#  0    +-----+-----+-----+--------------------------------------------+
#       0    0.25  0.51                                       1.574 1.78  1.98  x
#
# 구역: 급행 띠(EXPRESS)와 도크(WORK_DOCK, OUT_DOCK)만 잠그고 HALL이 나머지 바닥 전부다.
# HALL에서 로봇끼리는 Nav2가 피하므로 peer_obstacles를 켜야 한다(실물 nav2.launch.py 기본값은 false).
# 흐름: 충전 칸 -> 입구 E -> 남쪽 통로 -> 줄 입구 Q2 -> 앞자리 Q1 -> WORK -> 북쪽 W_X -> 급행 -> O_X -> OUTBOUND -> O_OUT.
# 출고가 막히면 W -> M_E -> O_IN -> OUTBOUND 우회로를 쓴다. 서는 지점은 도크와 급행 띠에서 0.135 이상 떨어뜨린다.
name: arena_v7
bounds: [0.0, 0.0, 1.98, 0.98]
# 좌표는 벽 아래 단차 면 기준이다(bounds 0.98 x 1.98). lidar 높이의 벽 면은 단차보다 0.006 바깥이고, 1 cm 지도에서는 같은 벽 칸에 든다.
# 2026-11-25 줄자(lidar 높이, 벽 면에서, 단차 0.006을 빼서 넣음): 남쪽 통로 0.37, 가운데 통로 0.35, 두께 0.04, 급행 약 0.20,
# 진열대 A 서쪽 끝 0.66, 남쪽 서쪽 진열대 서쪽 끝 0.71, 남쪽 진열대 길이 0.31, 틈 0.25. A와 남쪽 동쪽 진열대 동쪽 끝은 한 줄.
shelves:
  - [0.654, 0.754, 1.574, 0.794]     # 북쪽 긴 진열대 A(급행 남쪽)
  - [0.704, 0.364, 1.014, 0.404]     # 남쪽 진열대, 서쪽
  - [1.264, 0.364, 1.574, 0.404]     # 남쪽 진열대, 동쪽
  # 충전 칸막이. 5 cm 지도 칸 경계에 걸쳐도 칸을 다 칠한다(위치 추정은 1 cm 지도를 쓴다)
  - [0.24, 0.0, 0.26, 0.10]
  - [0.50, 0.0, 0.52, 0.10]
# 시뮬 전용 진열대(shelves와 같은 순서, 같은 개수). 지금은 shelves와 같다.
sim_shelves:
  - [0.654, 0.754, 1.574, 0.794]
  - [0.704, 0.364, 1.014, 0.404]
  - [1.264, 0.364, 1.574, 0.404]
  - [0.24, 0.0, 0.26, 0.10]
  - [0.50, 0.0, 0.52, 0.10]
# Nav2 계획만 막는 사각형(구역이 아니라 쥐지 않는다). 칸막이 1, 2 위 끝을 긁지 않게 막는다.
# 남쪽 진열대 사이 건넘 틈은 지름길이라 막지 않는다.
keepout_extra: [[0.19, 0.0, 0.31, 0.20], [0.45, 0.0, 0.57, 0.20]]
zones:
  # 넓은 바닥 전부. 진열대 자리는 어느 구역도 아니다
  HALL:
    kind: shared
    capacity: 3
    rects: [[0.0, 0.0, 1.98, 0.395], [0.0, 0.395, 1.78, 0.63], [0.0, 0.63, 1.98, 0.754],
            [0.0, 0.754, 0.598, 0.765], [1.574, 0.754, 1.98, 0.77], [0.50, 0.765, 0.598, 0.794]]
  # 도크와 급행 구역. W에 선 로봇은 HALL 한 자리를 쥔다
  WORK_DOCK: {kind: dock, rects: [[1.78, 0.395, 1.98, 0.63]]}
  J_E: {kind: dock, rects: [[1.574, 0.77, 1.98, 0.98]]}             # 급행 동쪽 입구, 한 대
  EXPRESS: {kind: lane, capacity: 2, rects: [[0.50, 0.794, 1.574, 0.98]]}
  OUT_DOCK: {kind: dock, rects: [[0.0, 0.765, 0.50, 0.98]]}
nodes:
  # 고정 경로와 도크는 벽에서 2 cm 안쪽이다. 급행 줄은 진열대 A 북쪽 면에서 0.088, 북쪽 벽에서 0.098 떨어진다(띠 가운데 0.887보다 0.5 cm 남쪽).
  W: {x: 1.86, y: 0.495, kind: dock, yaw_deg: 90}      # WORK, 남쪽에서 들어가 북쪽을 본다
  O: {x: 0.285, y: 0.882, kind: dock, yaw_deg: 180}     # OUTBOUND, 급행 서쪽 끝, 서쪽을 본다
  # 급행 들머리: W에서 북쪽으로 나와 도는 원호의 50도 점. WORK_DOCK에서 0.2 이상 떨어진다.
  W_X: {x: 1.8028, y: 0.8446, kind: pass}
  # 출고로 들어가는 점(O_IN)과 나가는 점(O_OUT). 도크 keepout 밖이고 OUT_DOCK에서 0.135 이상이다.
  # O_IN은 급행으로 오지 않는 로봇의 출고 대기 자리다. 서는 방향은 out_in 첫 구간 방향이다.
  O_IN: {x: 0.49, y: 0.625, kind: wait, yaw_deg: 110}
  # 급행 서쪽 끝 출고 대기 자리. 선 로봇이 급행을 쥐고, 출고가 비면 O로 들어간다.
  O_X: {x: 0.71, y: 0.882, kind: wait, yaw_deg: 180}
  O_OUT: {x: 0.18, y: 0.62, kind: fork}
  # 가운데 통로 동쪽 끝 우회 지점
  M_E: {x: 1.645, y: 0.55, kind: fork}
  # 남쪽 진열대 틈 아래 중간 지점(해결안 B). 나눈 goal에만 쓰고, 지도 이음은 Q2와만 있다
  GAP_S: {x: 1.12, y: 0.22, kind: fork, yaw_deg: -7.4, via: true}
  # WORK 대기 줄: 앞자리 Q1(W로 드는 원호 위), 줄 입구 Q2(남동 구석). 흐름은 Q2 -> Q1 -> W 한 방향이다.
  Q1: {x: 1.8491, y: 0.26, kind: wait, yaw_deg: 69.3}
  Q2: {x: 1.66, y: 0.15, kind: wait, yaw_deg: 0}
  # 충전 칸. 입구 E에서 북쪽을 보고 곧게 후진해 들어가고 앞으로 곧게 나온다
  P-1: {x: 0.12, y: 0.10, kind: parking, yaw_deg: 90}
  P-2: {x: 0.38, y: 0.10, kind: parking, yaw_deg: 90}
  P-3: {x: 0.64, y: 0.10, kind: parking, yaw_deg: 90}
  # 칸 입구. through: 이어진 Nav2 goal을 이 지점을 거쳐 한 goal로 합친다
  E-1: {x: 0.12, y: 0.24, kind: fork, yaw_deg: 90, through: true}
  E-2: {x: 0.38, y: 0.24, kind: fork, yaw_deg: 90, through: true}
  E-3: {x: 0.64, y: 0.24, kind: fork, yaw_deg: 90, through: true}
paths:  # 고정 경로(FollowPath 선). [x, y]는 꺾는 점
  # 줄 입구에서 W로: Q2 줄과 W 줄에 접하는 원호(반지름 0.17)
  q_step: {points: [Q2, [1.69, 0.15], [1.7195, 0.1526], [1.7481, 0.1603], [1.775, 0.1728],
                    [1.7993, 0.1898], [1.8202, 0.2107], [1.8372, 0.235], Q1]}
  work_in: {points: [Q1, [1.8572, 0.2895], [1.86, 0.32], W]}  # 원호 끝에서 W까지 북쪽으로 곧게
  # 급행으로 나가기: 북쪽으로 곧게 원호 앞까지 간 뒤 W_X로
  work_out: {points: [W, [1.86, 0.722], [1.8576, 0.7498], [1.8504, 0.7767], [1.8386, 0.802], [1.8226, 0.8248],
                      W_X]}
  # 급행: 출고로 갈 때만, 서쪽 한 방향. O_X에서 끊겨 출고가 바쁘면 O_X에서 기다린다
  express: {points: [W_X, [1.78, 0.8606], [1.7547, 0.8724], [1.7278, 0.8796], [1.7, 0.882], O_X, O]}
  # 넓은 곳에서 출고로(급행으로 오지 않는 로봇). 꺾는 점은 OUT_DOCK 안이다
  out_in: {points: [O_IN, [0.40, 0.882], O]}
  # 출고에서 나오기: 후진 없이 서쪽으로 갔다가 남쪽으로 꺾어 O_OUT으로
  out_out: {points: [O, [0.18, 0.854], O_OUT]}
  bay_in_1: {points: [E-1, P-1], reverse: true}        # 충전 칸: 후진으로 들어가 북쪽을 보고 선다
  bay_in_2: {points: [E-2, P-2], reverse: true}
  bay_in_3: {points: [E-3, P-3], reverse: true}
  bay_out_1: {points: [P-1, E-1]}                      # 앞으로 곧게 나온다
  bay_out_2: {points: [P-2, E-2]}
  bay_out_3: {points: [P-3, E-3]}
nav:  # Nav2 goal 이음(HALL 안). keepout, 진열대, 서 있는 로봇에 너무 가까운 쌍은 잇지 않는다
  - {nodes: [E-1, E-2, E-3]}
  - {nodes: [E-3, Q2]}
  - {nodes: [O_OUT, E-1]}
  - {nodes: [O_OUT, E-2]}
  - {nodes: [O_OUT, E-3]}
  - {nodes: [O_IN, E-1]}
  - {nodes: [O_IN, E-2]}
  - {nodes: [O_OUT, O_IN]}                             # 우회로로 가는 이음
  - {nodes: [O_IN, M_E]}                               # 우회로: 가운데 통로
  - {nodes: [M_E, Q2]}
  # WORK에서 넓은 곳으로 풀려 나가기: 한 방향 Nav2 goal. extra_m은 길 고르기에만 더하는 제자리 돌기 값이다
  - {nodes: [W, M_E], leave_dock: true, extra_m: 0.3}
  - {nodes: [GAP_S, Q2]}                               # 나눈 goal의 둘째 조각(splits)
# 나눈 goal(해결안 B, plan_split이 켜졌을 때만): from 사각형에서 to로 가는 Nav2 goal을 via를 거쳐 둘로 보낸다
# 사각형은 두 길의 NavFn 비용이 15 % 안으로 비슷한 자리다(근거 docs/plan_flip_2026-11-24/two_ways.py)
splits:
  - {to: Q2, via: GAP_S, from: [[0.75, 0.404, 1.20, 0.803], [0.0, 0.404, 0.40, 0.803]]}
  - {to: Q2, via: M_E, from: [[0.40, 0.51, 0.75, 0.803], [0.575, 0.404, 0.75, 0.51]]}
stations:
  WORK: {dock: W, queue: [Q1, Q2], line: true, server: workcell, arms: [arm_left, arm_right], action: fill}
  # 대기 자리 둘 중 길 값이 싼 쪽으로 간다(W에서는 급행 끝 O_X, 넓은 곳에서는 O_IN)
  OUTBOUND: {dock: O, queue: [O_IN, O_X], server: arm_ship, arms: [arm_ship], action: swap}
parking: [P-1, P-2, P-3]
